contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 a, uint256 d, uint256 s) public {
        require(spender != address(0));
        require(a + d >= a); // no overflow

        // setup: establish an allowance of a
        c.approve(spender, a);
        uint256 before = c.allowance(address(this), spender);
        assert(before == a);

        // increase allowance by d (must always succeed)
        c.increaseAllowance(spender, d);
        uint256 afterIncrease = c.allowance(address(this), spender);
        assert(afterIncrease == a + d);

        // decrease by s: succeeds only if s <= allowance, and then lowers by exactly s
        bool reverted;
        if (s <= a + d) {
            c.decreaseAllowance(spender, s);
            reverted = false;
        } else {
            try c.decreaseAllowance(spender, s) { reverted = false; }
            catch { reverted = true; }
        }

        if (s <= a + d) {
            assert(!reverted && c.allowance(address(this), spender) == a + d - s);
        } else {
            assert(reverted && c.allowance(address(this), spender) == a + d);
        }
    }
}

contract InvMutTest {
