}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 b) public {
        uint256 balBefore = c.balanceOf(address(this));
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.burn(b) { reverted = false; }
        catch { reverted = true; }

        uint256 balAfter = c.balanceOf(address(this));
        uint256 supplyAfter = c.totalSupply();

        if (reverted) {
            assert(b > balBefore && balAfter == balBefore && supplyAfter == supplyBefore);
        } else {
            assert(b <= balBefore && balAfter + b == balBefore && supplyAfter + b == supplyBefore);
        }
    }

    receive() external payable {}
}

