contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address spender, uint256 a, uint256 b, uint256 d) public {
        require(spender != address(0));
        require(a <= type(uint256).max - b);
        bool decReverted;
        c.approve(spender, a);
        c.increaseAllowance(spender, b);
        uint256 expected = a + b;
        if (d > expected) {
            try c.decreaseAllowance(spender, d) { decReverted = false; } catch { decReverted = true; }
        } else {
            c.decreaseAllowance(spender, d);
            decReverted = false;
        }
        uint256 finalAllowance = c.allowance(address(this), spender);
        if (d > expected) {
            assert(decReverted && finalAllowance == expected);
        } else {
            assert(!decReverted && finalAllowance == expected - d);
        }
    }
    receive() external payable {}
}

