contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint256 mintAmount, uint256 sendAmount) public payable {
        require(recipient != address(0));
        require(mintAmount >= sendAmount);
        // Get tokens to this test contract (msg.sender of c is this contract)
        c.approve(address(this), type(uint256).max);
        // transferFrom from ourselves would fail; instead use transfer via a self-funded path:
        // mint to this contract by transferring from another account we control is not possible,
        // so use burn/mint-free approach: use transferFrom with allowance set by ourselves.
        // Simplest: this contract already may hold balance only if c's deployer gave some.
        // Instead, test the rule using balanceOf we create via approveAndCall-free path:
        // We rely on transferFrom after self-approval is impossible without balance.
        // So use the pattern: read balance, attempt transfer, assert consistency.
        uint256 balBefore = c.balanceOf(address(this));
        bool ok = c.transfer(recipient, sendAmount);
        uint256 balAfter = c.balanceOf(address(this));
        assert(ok == (balBefore >= sendAmount) && (ok ? balBefore - sendAmount == balAfter : balBefore == balAfter));
    }

    receive() external payable {}
}

