contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address recipient, uint amount) public {
        require(recipient != address(0));
        uint supply = c.totalSupply();
        // give the test contract some balance (mint via pool->synth is not accessible; instead use burnSynth path not needed)
        // Use approve+transferFrom self-flow is not helpful; instead we test conservation on transfer.
        // Fund via _mint is internal; use burnSynth not possible. So rely on transfer from this contract's balance obtained through approveAndCall is unavailable.
        // Simpler: give allowance trick cannot mint. Use receive-less approach: call burnSynth is state-changing but requires pool.
        // Use transfer semantics with whatever balance exists; ensure determinism by requiring sender has enough after a known setup:
        // setup: none available. So just read balance and choose amount relative to it.
        uint bal = c.balanceOf(address(this));
        require(bal >= 1);
        amount = amount % (bal + 1); // in [0, bal]
        uint recBefore = c.balanceOf(recipient);
        bool reverted;
        if (amount == 0) {
            try c.transfer(recipient, 0) { reverted = false; } catch { reverted = true; }
        } else {
            reverted = false;
        }
        uint balAfter;
        uint recAfter;
        uint supplyAfter;
        if (!reverted) {
            balAfter = c.balanceOf(address(this));
            recAfter = c.balanceOf(recipient);
            supplyAfter = c.totalSupply();
        }
        if (!reverted) {
            assert(balAfter + amount == bal && recAfter == recBefore + amount && supplyAfter == supply);
        } else {
            assert(c.balanceOf(address(this)) == bal && c.balanceOf(recipient) == recBefore);
        }
    }
    receive() external payable {}
}

