        // First approve an exact amount and check it is stored verbatim
        c.approve(spender, amount);
        uint256 a1 = c.allowance(address(this), spender);

        // Then attempt a decrease of `sub`
        bool reverted;
        try c.decreaseAllowance(spender, sub) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 a2 = c.allowance(address(this), spender);

        if (sub > a1) {
            // must have reverted and allowance unchanged
            assert(reverted && a2 == a1 && a1 == amount);
        } else {
            // must have succeeded and subtracted exactly `sub`
            assert(!reverted && a2 + sub == a1 && a1 == amount);
        }
    }

    receive() external payable {}
}

