contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address recipient, uint256 amount, uint256 excess) public {
        require(recipient != address(0));
        require(amount > 0);
        require(excess > 0);
        // Fund this test contract by having it burn-proof: mint via _mint is not public,
        // so use transferFrom with max-approval path is impossible; instead we use the
        // deployer relationship: this contract IS msg.sender for c, so it can burn only
        // if it has balance. Instead, test on balances achievable via transfer of zero is
        // not allowed (amount>0). Use approve/transferFrom self-mint is impossible.
        // Workaround: transfer from a fresh start reverts for over-balance; for the
        // success path we need balance. The only way to obtain balance is via external
        // surface: none mints to us. So restrict to the revert rule plus state preservation.
        uint256 balBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(recipient);
        uint256 supplyBefore = c.totalSupply();

        bool reverted;
        try c.transfer(recipient, balBefore + excess) { reverted = false; }
        catch { reverted = true; }

        assert(reverted
            && c.balanceOf(address(this)) == balBefore
            && c.balanceOf(recipient) == recipientBefore
            && c.totalSupply() == supplyBefore);
    }
    receive() external payable {}
}

